CREATE     PROCEDURE [synapse_fo].[usp_Insert_CUSTTRANSOPEN]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:42
	Description: Insert stored procedure for CUSTTRANSOPEN from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[CUSTTRANSOPEN]
	(
		[ACCOUNTNUM],
		[AMOUNTCUR],
		[AMOUNTMST],
		[BANKDISCNOTICEDEADLINE],
		[BANKLCEXPORTLINE],
		[CASHDISCDATE],
		[CASHDISCOUNTLEDGERDIMENSION],
		[COLLECTIONLETTER],
		[COLLECTIONLETTERCODE],
		[COVSTATUS],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DUEDATE],
		[EXCHADJUNREALIZED],
		[EXCHADJUNREALIZEDREPORTING],
		--[FileName],
		[FINEAMOUNT_BR],
		[FINEAMOUNTPAYMCUR_BR],
		[FINECODE_BR],
		[INTERESTAMOUNT_BR],
		[INTERESTAMOUNTPAYMCUR_BR],
		[INTERESTCODE_BR],
		[LASTINTERESTDATE],
		[LastProcessedChange_DateTime],
		--[LSN],
		[PARTITION],
		[POSSIBLECASHDISC],
		[RECID],
		[RECVERSION],
		[REFRECID],
		[REPORTINGCURRENCYAMOUNT],
		[SETTLEDLINEPERCENT_IN],
		[SETTLEDTOTALAMOUNT_IN],
		[SETTLEMENTPRIORITYCASHDISCDATE],
		--[SKS_EPY_SENTTOEPAY],
		--[SysRowId],
		[TAXDISTRIBUTION],
		[TAXWITHHOLDAMOUNTORIGIN_IN],
		[TCSAMOUNT_IN],
		[TDSAMOUNT_IN],
		[TRANSDATE],
		[USECASHDISC]
	)
	SELECT 
		stg.[ACCOUNTNUM],
		stg.[AMOUNTCUR],
		stg.[AMOUNTMST],
		stg.[BANKDISCNOTICEDEADLINE],
		stg.[BANKLCEXPORTLINE],
		stg.[CASHDISCDATE],
		stg.[CASHDISCOUNTLEDGERDIMENSION],
		stg.[COLLECTIONLETTER],
		stg.[COLLECTIONLETTERCODE],
		stg.[COVSTATUS],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DUEDATE],
		stg.[EXCHADJUNREALIZED],
		stg.[EXCHADJUNREALIZEDREPORTING],
		--stg.--[FileName],
		stg.[FINEAMOUNT_BR],
		stg.[FINEAMOUNTPAYMCUR_BR],
		stg.[FINECODE_BR],
		stg.[INTERESTAMOUNT_BR],
		stg.[INTERESTAMOUNTPAYMCUR_BR],
		stg.[INTERESTCODE_BR],
		stg.[LASTINTERESTDATE],
		stg.[LastProcessedChange_DateTime],
		--stg.--[LSN],
		stg.[PARTITION],
		stg.[POSSIBLECASHDISC],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[REFRECID],
		stg.[REPORTINGCURRENCYAMOUNT],
		stg.[SETTLEDLINEPERCENT_IN],
		stg.[SETTLEDTOTALAMOUNT_IN],
		stg.[SETTLEMENTPRIORITYCASHDISCDATE],
		--stg.[SKS_EPY_SENTTOEPAY],
		--stg.--[SysRowId],
		stg.[TAXDISTRIBUTION],
		stg.[TAXWITHHOLDAMOUNTORIGIN_IN],
		stg.[TCSAMOUNT_IN],
		stg.[TDSAMOUNT_IN],
		stg.[TRANSDATE],
		stg.[USECASHDISC]	
	FROM [staging_fo].[CUSTTRANSOPEN] stg
		LEFT JOIN [synapse_fo].[CUSTTRANSOPEN] tgt
			ON stg.[RECID] = tgt.[RECID] 
		
	WHERE tgt.[RECID] IS NULL
END
